import JsonlSessionPersistence from './index.js'
import { isDeepStrictEqual } from 'node:util'

/** The native persistBatch appends and fsyncs; read() rescans the real artifact. */
export function createJsonlWindowBarrier(handle, session) {
  if (!(handle?.storage instanceof JsonlSessionPersistence) || handle.access !== 'write' || handle.id !== session.id) throw new Error('WINDOW_JSONL_WRITE_HANDLE_REQUIRED')
  const storage=handle.storage
  const routed=storage.ctx.get?.('sessions')?.get(session.id)===session
  function assertOwner() {
    if (handle.closing!==undefined || storage.tracker.writers.get(session.id)!==handle
      || routed && storage.ctx.get?.('sessions')?.get(session.id)!==session) throw new Error('WINDOW_JSONL_OWNER_CHANGED')
  }
  let chain = Promise.resolve()
  const read = async () => { assertOwner(); return (await handle.read()).events }
  function persist() {
    const operation = chain.then(async () => {
      const before = await read(), snapshot = session.snapshotEvents()
      if (!isDeepStrictEqual(snapshot.slice(0, before.length), before)) throw new Error('WINDOW_JSONL_PREFIX_CONFLICT')
      // Published sessions already route every event to this same writer.
      // Appending that suffix manually would poison its buffered drain.
      if (routed) await handle.drainLive()
      else await handle.append(snapshot.slice(before.length))
      await handle.flush()
      const disk = await read()
      if (!isDeepStrictEqual(disk.slice(0, snapshot.length), snapshot)
        || routed && !isDeepStrictEqual(session.snapshotEvents().slice(0,disk.length),disk)) throw new Error('WINDOW_JSONL_READBACK_MISMATCH')
      return { durable: true, throughSeq: snapshot.length - 1, barrier: 'persistBatch.appendLines/materialize.fsync+exact-readback',
        writerPath:routed?'existing-published-event-route':'standalone-exact-suffix' }
    })
    chain = operation.catch(() => {})
    return operation
  }
  return Object.freeze({ read, persist, kind: 'native-jsonl-fsync-readback-v1', sessionId: session.id })
}
